// ============================================
// VALIDATION INPUT - LLM Call Messages (BYOT)
// ============================================

const input = $input.first().json;
const body = input.body || input;
const ctx = body.context || {};

const errors = [];

// --- REQUIRED: provider ---
const provider = (body.provider || ctx.provider || '').toLowerCase();
const validProviders = ['anthropic', 'openai', 'mistral', 'google'];
if (!provider) {
  errors.push('provider requis (anthropic, openai, mistral, google)');
} else if (!validProviders.includes(provider)) {
  errors.push(`provider invalide: ${provider} (doit etre: ${validProviders.join(', ')})`);
}

// --- REQUIRED: model ---
const model = body.model || ctx.model;
if (!model || typeof model !== 'string' || model.trim().length === 0) {
  errors.push('model requis (ex: claude-haiku-4-5-20251001, gpt-4o)');
}

// --- REQUIRED: api_key (BYOT - NO FALLBACK) ---
const apiKey = body.api_key || ctx.api_key;
if (!apiKey || typeof apiKey !== 'string' || apiKey.trim().length === 0) {
  errors.push('api_key requis (BYOT pattern - aucun fallback sur env)');
}

// --- REQUIRED: messages ---
const messages = body.messages || ctx.messages;
if (!messages || !Array.isArray(messages) || messages.length === 0) {
  errors.push('messages requis (array non vide)');
}

// --- Optional: system prompt ---
const system = body.system || ctx.system || null;

// --- Optional: max_tokens ---
const maxTokens = parseInt(body.max_tokens || ctx.max_tokens || 4096);
if (isNaN(maxTokens) || maxTokens < 1 || maxTokens > 200000) {
  errors.push('max_tokens doit etre entre 1 et 200000');
}

// --- Optional: temperature ---
const temperature = parseFloat(body.temperature ?? ctx.temperature ?? 0.7);
if (isNaN(temperature) || temperature < 0 || temperature > 2) {
  errors.push('temperature doit etre entre 0 et 2');
}

// --- Passthrough metadata ---
const metadata = body.metadata || ctx.metadata || {};

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    metadata: metadata
  };
}

// Les modèles de raisonnement d'OpenAI n'acceptent ni `max_tokens` ni une
// `temperature` autre que 1 (azy.daily#276).
//
// L'appelant peut le DIRE, et sa parole prime : le catalogue connaît la capacité
// du modèle, nous la devinons. Deviner sur l'identifiant est un pis-aller qui
// rate ce qu'il ne reconnaît pas — remonté par l'équipe mobile.
//
// Le repli par motif ne couvre QUE le nommage d'OpenAI, et volontairement :
// Gemini accepte `temperature` sur ses modèles à raisonnement, Anthropic aussi
// tant que `thinking` n'est pas activé. Étendre la garde aux autres providers
// leur retirerait des paramètres qui fonctionnent.
const MODELE_RAISONNEMENT = /^(?:openai\/)?(?:chat)?gpt-5|^(?:openai\/)?o[1-9]/i;
const raisonnement = body.reasoning ?? ctx.reasoning ??
  (provider === 'openai' && MODELE_RAISONNEMENT.test((model || '').trim()));

return {
  valid: true,
  provider: provider,
  model: model.trim(),
  raisonnement: raisonnement,
  api_key: apiKey.trim(),
  system: system,
  messages: messages,
  max_tokens: maxTokens,
  temperature: temperature,
  metadata: metadata,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  metadata: input.metadata,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0
  }
};

